import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// Construction circles spread apart, cut to a search pill that grows and
// straightens, the copy types in and the graphic panel opens behind it.
// Frames on the 30 fps scene timeline, after `speed`. The ids are public: a
// saved `timing` prop refers to them.

type SearchRevealElementId = "circles" | "field" | "typing" | "panel";

interface SearchRevealTimingProps {
  text?: string;
  framesPerCharacter?: number;
}

const finite = (value: number | undefined, fallback: number) =>
  typeof value === "number" && Number.isFinite(value) ? value : fallback;
const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));
const letters = (text: string) =>
  Array.from(
    new Intl.Segmenter("en", { granularity: "grapheme" }).segment(text),
    (part) => part.segment,
  );

// The circles run until the cut to the field. The field grows over its
// length, its height and tilt settle over `grow` and `tilt`, the search icon
// fades in at `iconAt`. Typing lands a letter every `step` frames, the caret
// shows from `caretAt` (before the first letter) and blinks every `blink`
// once the copy is in; the scene holds `hold` frames after it. The panel
// fades in over `fade` and opens over its length.
const searchRevealTimeline = defineTimeline<
  SearchRevealElementId,
  SearchRevealTimingProps
>((props): TimelineElement<SearchRevealElementId>[] => {
  const text = props.text ?? "remocn";
  const characters = letters(text);
  const step = clamp(finite(props.framesPerCharacter, 4), 1, 12);
  return [
    {
      id: "circles",
      lane: "Shape",
      label: "circles",
      start: 0,
      length: 26,
    },
    {
      id: "field",
      lane: "Shape",
      label: "field",
      start: 26,
      length: 22,
      follows: "circles",
      beats: { grow: 20, tilt: 21, iconAt: 8, icon: 12 },
    },
    {
      id: "typing",
      lane: "Text",
      label: text,
      start: 54,
      length: characters.length * step,
      follows: "field",
      beats: { step, caretAt: -2, blink: 12, hold: 10 },
    },
    {
      id: "panel",
      lane: "Panel",
      label: "panel",
      start: 56,
      length: 34,
      follows: "field",
      beats: { fade: 4 },
    },
  ];
});

type SearchRevealProps = {
  text?: string;
  fieldWidth?: number;
  fontSize?: number;
  framesPerCharacter?: number;
  showPanel?: boolean;
  showGuides?: boolean;
  color?: string;
  fieldColor?: string;
  ringColor?: string;
  panelColor?: string;
  accentColor?: string;
  backgroundColor?: string;
  speed?: number;
  reducedMotion?: boolean;
  className?: string;
  /**
   * Moves, trims or stretches the circles, the field, the typing and the
   * panel, by the ids in `./timeline`.
   * Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<SearchRevealElementId>;
};

const searchRevealLength = 90;
const curve = Easing.bezier(0.22, 1, 0.36, 1);
const tween = (frame: number, start: number, end: number, from = 0, to = 1) =>
  interpolate(frame, [start, end], [from, to], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: curve,
  });

/** The schedule without `timing`, for the helpers called outside a render. */
const scheduleOf = (props: SearchRevealProps) =>
  resolve(searchRevealTimeline(props, { length: searchRevealLength }));

function searchRevealPlan(
  props: SearchRevealProps,
  tl: ResolvedTimeline<SearchRevealElementId>,
) {
  const characters = letters(props.text ?? "remocn");
  const typing = tl.get("typing");
  const end = Math.max(
    searchRevealLength,
    tl.get("panel").end,
    typing.end + typing.beat("hold"),
  );
  return { characters, end, speed: Math.max(0, finite(props.speed, 1)) };
}

/** Demo duration at 30 fps, including an 18-frame final hold. */
function getSearchRevealDuration(props: SearchRevealProps = {}) {
  const { end, speed } = searchRevealPlan(props, scheduleOf(props));
  return speed === 0 ? 1 : Math.ceil((end + 18) / speed);
}

/**
 * Frame is expressed at 30 fps; playback speed is applied here. `tl` is the
 * resolved schedule; without it the one `props` give, with no `timing`.
 */
function getSearchRevealState(
  frame: number,
  props: SearchRevealProps = {},
  tl: ResolvedTimeline<SearchRevealElementId> = scheduleOf(props),
) {
  const { characters, end, speed } = searchRevealPlan(props, tl);
  const circles = tl.get("circles");
  const field = tl.get("field");
  const typing = tl.get("typing");
  const panel = tl.get("panel");
  const step = typing.beat("step");
  const caretAt = typing.start + typing.beat("caretAt");
  const iconAt = field.start + field.beat("iconAt");
  const t = props.reducedMotion ? end : Math.max(0, finite(frame, 0)) * speed;
  const typedCount = clamp(
    Math.floor((t - typing.start) / step),
    0,
    characters.length,
  );
  const width = clamp(finite(props.fieldWidth, 464), 320, 640);
  const reveal =
    props.showPanel === false ? 0 : tween(t, panel.start, panel.end);
  const fieldWidth = tween(t, field.start, field.end, 130, width);
  const fieldHeight = tween(
    t,
    field.start,
    field.start + field.beat("grow"),
    24,
    80,
  );
  const panelWidth =
    fieldWidth + (Math.max(774, width + 170) - fieldWidth) * reveal;
  const panelHeight = fieldHeight + (374 - fieldHeight) * reveal;
  return {
    t,
    end,
    typedCount,
    text: characters.slice(0, typedCount).join(""),
    circleRadius: tween(t, circles.start, circles.end, 250, 410),
    circleOffset: tween(t, circles.start, circles.end, 62, 185),
    circlesVisible: t < circles.end,
    fieldVisible: t >= field.start,
    fieldWidth,
    fieldHeight,
    tilt: tween(t, field.start, field.start + field.beat("tilt"), -4, 0),
    iconOpacity: tween(t, iconAt, iconAt + field.beat("icon")),
    panelWidth,
    panelHeight,
    panelRadius: 40 * (1 - reveal),
    panelOpacity: tween(t, panel.start, panel.start + panel.beat("fade")),
    reveal,
    caretVisible:
      t >= caretAt &&
      t < end &&
      (typedCount < characters.length ||
        Math.floor((t - caretAt) / typing.beat("blink")) % 2 === 0),
  };
}

function Cross({ x, y, size = 9 }: { x: number; y: number; size?: number }) {
  return (
    <path
      d={`M ${x - size} ${y} H ${x + size} M ${x} ${y - size} V ${y + size}`}
    />
  );
}

/** A video scene: expanding construction circles, a search pill, and typed copy. */
function SearchRevealBase(props: SearchRevealProps) {
  const {
    text = "remocn",
    fieldWidth = 464,
    fontSize = 34,
    showPanel = true,
    showGuides = true,
    color = "#26232b",
    fieldColor = "#ffffff",
    ringColor = "#cbc5cf",
    panelColor = "#a800b7",
    accentColor = "#e8f99a",
    backgroundColor = "#f5f1f5",
    speed = 1,
    reducedMotion = false,
    className,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    searchRevealTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const state = getSearchRevealState(
    (frame * 30) / fps,
    {
      text,
      fieldWidth,
      showPanel,
      speed,
      reducedMotion,
    },
    tl,
  );
  const scale = Math.min(width / 1280, height / 720);
  const fittedFont = Math.min(
    clamp(finite(fontSize, 34), 18, 54),
    (state.fieldWidth - 120) / Math.max(1, letters(text).length * 0.65),
  );
  // The pill grows about its centre. Its corner rides that growth as a
  // transform from where the settled pill sits, not by `left`/`top`: layout
  // rounds a box edge to whole pixels, so a corner eased by layout clicks.
  const settled = getSearchRevealState(
    0,
    {
      text,
      fieldWidth,
      showPanel,
      speed,
      reducedMotion: true,
    },
    tl,
  );
  const fieldDx = (settled.fieldWidth - state.fieldWidth) / 2;
  const fieldDy = (settled.fieldHeight - state.fieldHeight) / 2;
  const fieldShift =
    Math.abs(fieldDx) < 1e-3 && Math.abs(fieldDy) < 1e-3
      ? undefined
      : `translate(${fieldDx}px, ${fieldDy}px)`;
  // The icon is laid out against the settled pill too: pinned by `right` and
  // centred by the flex box, it would ride the growth through layout.
  const iconDx = state.fieldWidth - settled.fieldWidth;
  const iconDy = (state.fieldHeight - settled.fieldHeight) / 2;
  const iconShift =
    Math.abs(iconDx) < 1e-3 && Math.abs(iconDy) < 1e-3
      ? undefined
      : `translate(${iconDx}px, ${iconDy}px)`;
  const markerWidth = showPanel ? state.panelWidth : state.fieldWidth;
  const markerHeight = showPanel ? state.panelHeight : state.fieldHeight;

  return (
    <AbsoluteFill
      className={className}
      style={{
        backgroundColor,
        overflow: "hidden",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          width: 1280,
          height: 720,
          flexShrink: 0,
          position: "relative",
          transform: `scale(${scale})`,
        }}
      >
        {state.circlesVisible && (
          <svg
            aria-hidden="true"
            width="1280"
            height="720"
            viewBox="-640 -360 1280 720"
            style={{ position: "absolute", inset: 0, overflow: "visible" }}
          >
            <g fill="none" stroke={ringColor} strokeWidth="1">
              {[-1, 1].map((side) => (
                <g key={side}>
                  <circle
                    cx={side * state.circleOffset}
                    r={state.circleRadius}
                  />
                  {showGuides &&
                    [-1, 1].map((edge) => (
                      <Cross
                        key={edge}
                        x={
                          side * state.circleOffset + edge * state.circleRadius
                        }
                        y={0}
                        size={6}
                      />
                    ))}
                </g>
              ))}
            </g>
          </svg>
        )}
        {state.fieldVisible && (
          <div
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              width: 0,
              height: 0,
              transform: `rotate(${state.tilt}deg)`,
            }}
          >
            {showPanel && (
              <div
                style={{
                  position: "absolute",
                  left: -state.panelWidth / 2,
                  top: -state.panelHeight / 2,
                  width: state.panelWidth,
                  height: state.panelHeight,
                  borderRadius: state.panelRadius,
                  overflow: "hidden",
                  opacity: state.panelOpacity,
                  backgroundColor: panelColor,
                }}
              >
                <svg
                  aria-hidden="true"
                  width="844"
                  height="374"
                  viewBox="0 0 844 374"
                  style={{
                    position: "absolute",
                    left: "50%",
                    top: "50%",
                    transform: `translate(-50%, -50%) scale(${1.07 - state.reveal * 0.07})`,
                  }}
                >
                  <g
                    transform={`translate(310 -45) rotate(${-24 + 10 * state.reveal})`}
                    fill="none"
                    stroke={fieldColor}
                  >
                    {Array.from({ length: 30 }, (_, i) => (
                      <ellipse
                        key={i}
                        rx={82 + i * 3}
                        ry={118}
                        transform={`rotate(${i * 6})`}
                        strokeWidth="1.4"
                        opacity={0.35 + i / 70}
                      />
                    ))}
                  </g>
                  <g
                    transform={`translate(65 233) rotate(${state.reveal * 25})`}
                    fill={accentColor}
                  >
                    {Array.from({ length: 10 }, (_, i) => (
                      <ellipse
                        key={i}
                        cy="-41"
                        rx="19"
                        ry="48"
                        transform={`rotate(${i * 36})`}
                      />
                    ))}
                  </g>
                  <g
                    transform={`translate(720 357) rotate(${-18 * state.reveal})`}
                    fill="none"
                    stroke={accentColor}
                    strokeWidth="22"
                  >
                    <path d="M -68 -115 V 80 M -122 -60 L -14 26 M -125 18 L -12 -61" />
                    <circle cx="103" cy="-35" r="54" />
                  </g>
                </svg>
              </div>
            )}
            {showGuides && (
              <svg
                aria-hidden="true"
                width="1280"
                height="720"
                viewBox="-640 -360 1280 720"
                style={{
                  position: "absolute",
                  left: -640,
                  top: -360,
                  overflow: "visible",
                }}
              >
                <g
                  fill="none"
                  stroke={ringColor}
                  strokeWidth="1"
                  opacity={0.5 * state.iconOpacity}
                >
                  <path
                    d={`M ${markerWidth / 2} ${-markerHeight / 2 - 14} V -360 M ${-markerWidth / 2} ${markerHeight / 2 + 14} V 360`}
                  />
                </g>
                <g fill="none" stroke={color} strokeWidth="1.5">
                  <Cross x={-markerWidth / 2} y={markerHeight / 2} />
                  <Cross x={markerWidth / 2} y={-markerHeight / 2} />
                </g>
              </svg>
            )}
            <div
              style={{
                position: "absolute",
                left: -settled.fieldWidth / 2,
                top: -settled.fieldHeight / 2,
                transform: fieldShift,
                width: state.fieldWidth,
                height: state.fieldHeight,
                borderRadius: 999,
                backgroundColor: fieldColor,
                boxShadow: "0 3px 12px #26232b08, inset 0 0 0 1px #26232b0a",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                overflow: "hidden",
                color,
                fontFamily: "Arial, Helvetica, sans-serif",
                fontSize: fittedFont,
                fontWeight: 400,
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  maxWidth: state.fieldWidth - 116,
                  overflow: "hidden",
                  whiteSpace: "pre",
                }}
              >
                <span>{state.text}</span>
                <span
                  aria-hidden="true"
                  style={{
                    width: 1.5,
                    height: fittedFont * 1.12,
                    marginLeft: 2,
                    flexShrink: 0,
                    backgroundColor: color,
                    opacity: state.caretVisible ? 1 : 0,
                  }}
                />
              </div>
              <svg
                aria-hidden="true"
                width="28"
                height="28"
                viewBox="0 0 28 28"
                fill="none"
                stroke={ringColor}
                strokeWidth="1.5"
                strokeLinecap="round"
                style={{
                  position: "absolute",
                  ...(iconShift
                    ? {
                        left: settled.fieldWidth - 24 - 28,
                        top: (settled.fieldHeight - 28) / 2,
                        transform: iconShift,
                      }
                    : { right: 24 }),
                  opacity: state.iconOpacity,
                }}
              >
                <circle cx="11.5" cy="11.5" r="7.5" />
                <path d="m17 17 7 7" />
              </svg>
            </div>
